import {ReviewAPIClient} from './review-api-client.mjs';
import {materialKey} from './presentation.mjs';
const names={scope:'复现目标',code:'代码与版本',data:'数据与划分',environment:'环境重建',settings:'实验设置',workflow:'执行流程',resources:'计算与预算',results:'结果验收'};
const statuses={queued:'等待审阅',running:'正在审阅',completed:'审阅完成',failed:'审阅失败',cancelled:'已取消'};
export class APIReviewWorkspace{
 constructor(intake){this.i=intake;this.selected=null;this.base=location.origin;this.health=null;this.token='';this.consent=false;this.busy=false;this.error='';this.timer=null;this.generation=0;}
 client(base=this.base){return new ReviewAPIClient(base,fetch,{token:base===this.base?this.token:''});}
 projects(){return this.i.projects;}
 current(){return this.projects().find(p=>p.id===this.selected)||this.projects()[0];}
 render(){const e=x=>this.i.esc(x),p=this.current(),entry=p?.api_review,stale=entry&&entry.material_key!==materialKey(p);return `<section class="api-review-workspace"><div class="demo-notice"><strong>真实 API 接入</strong><span>向配置的 HTTP 服务提交材料；模型网关生成静态审阅建议，不执行论文代码。</span></div><div class="api-config"><div class="field"><label for="review-api-base">评测 API 地址</label><input id="review-api-base" data-review-base value="${e(this.base)}" placeholder="https://your-service.example"><small>模型 URL、模型名称与 API key 在服务端配置。</small></div><div class="field"><label for="review-access-code">网站审阅访问码</label><input id="review-access-code" type="password" data-review-token autocomplete="off" placeholder="${this.token?'已填写，本页有效':'由网站管理员提供'}" ${this.busy?'disabled':''}><small>仅本页内存保存；这里不填写模型供应商密钥。</small></div><button class="btn" data-review-action="connect" ${this.busy?'disabled':''}>检查连接</button><span class="api-connection-state">${this.health?this.health.configured?this.health.mode==='synchronous'?'云端模型已连接 · 单次审阅':'服务已配置模型':'服务已连接 · 模型未配置':'尚未检查连接'}</span></div>${this.error?`<p class="error-box" role="alert">${e(this.error)}</p>`:''}<div class="field"><label for="review-api-project">选择材料项目</label><select id="review-api-project" data-review-project ${this.busy?'disabled':''}>${this.projects().length?this.projects().map(x=>`<option value="${e(x.id)}" ${x.id===p?.id?'selected':''}>${e(x.title||'未命名项目')}</option>`).join(''):'<option value="">先导入论文与代码材料</option>'}</select></div>${p?`<div class="demo-materials"><div><span>论文 PDF</span><strong>${e(p.paper?.name||'未导入')}</strong><small>${p.paper?.pages?.length||0} 页正文</small></div><div><span>代码 ZIP</span><strong>${e(p.repository?.name||'未导入')}</strong><small>${p.repository?.blob?'原始 ZIP 可提交':'需要原始 ZIP，目录线索不能代替源文件'}</small></div></div><label class="presentation-opt-in"><input type="checkbox" data-review-consent ${this.consent?'checked':''} ${this.busy?'disabled':''}><span>允许将本项目 PDF 与 ZIP 发送到上方 API 地址；模型服务可能产生费用。</span></label><div class="source-actions"><button class="btn primary" data-review-action="submit" ${this.busy||!this.consent||!p.paper?.blob||!p.repository?.blob?'disabled':''}>${this.busy?'正在请求 API…':'提交至 API 进行静态审阅'}</button>${entry?.job&&entry.mode!=='synchronous'?`<button class="btn" data-review-action="refresh" ${this.busy?'disabled':''}>刷新任务</button>${['queued','running'].includes(entry.job.status)&&!stale?'<button class="btn" data-review-action="cancel">取消当前审阅</button>':''}`:''}<button class="btn text" data-review-action="materials">查看项目材料</button></div>${this.busy?'<p class="info-strip" role="status" aria-live="polite">正在等待 API 返回。云端单次审阅包含材料解析和模型处理，请保持页面打开。</p>':''}${stale?'<p class="info-strip">材料已变化，下方保留旧版本任务。重新提交后读取本次材料的结果。</p>':''}${entry?.job?`<section class="api-job"><div class="section-heading"><h2>${e(statuses[entry.job.status])}</h2><code>${e(entry.job.id)}</code></div><p>${e(entry.job.stage||'阶段未记录')} · ${e(entry.base)}</p>${entry.mode==='synchronous'?'<p class="info-strip">云端报告已返回并保存在本浏览器；可导出备份。</p>':''}${entry.job.error?`<p class="error-box">${e(entry.job.error.message)}</p>`:''}${entry.report?this.report(entry):'<p class="assessment-empty">尚无报告。界面仅展示服务返回的状态，不使用预设结果填充。</p>'}</section>`:''}`:`<div class="execution-empty"><h2>先准备一个论文项目</h2><p>在论文项目导入 PDF 与代码 ZIP，随后回到这里选择并提交。</p><button class="btn" data-review-action="new">导入材料</button></div>`}<details class="api-start-guide"><summary>启动 HTTP 服务与配置模型</summary><pre>python -m articheck.review_api --port 8790 --with-ui
# 服务端设置 ARTICHECK_REVIEW_BASE_URL、ARTICHECK_REVIEW_MODEL、ARTICHECK_API_KEY
# 模型配置为空时返回 provider_not_configured，不生成审阅结果</pre><p>浏览器跨域由部署方配置；本地建议直接打开服务自带界面 http://127.0.0.1:8790/#api-review 。纯命令行客户端见仓库 docs/API_REVIEW.md。</p></details></section>`;}
 report(entry){const r=entry.report,e=x=>this.i.esc(x);return `<div class="demo-notice"><strong>模型静态建议</strong><span>来源 model_api_static_review；未运行代码，未验收实验结论。</span></div><div class="section-heading"><h3>${e(r.review.summary)}</h3><button class="btn" data-review-action="export">导出 API 报告</button></div><div class="demo-dimensions">${r.review.criteria.map(row=>`<div><span>${e(names[row.dimension]||row.dimension)}</span><strong>${e({documented:'材料有记录',needs_review:'需要复核',missing:'缺少依据'}[row.status]||row.status)}</strong></div><p>${e(row.note)}</p>`).join('')}</div>${r.budget?`<p class="info-strip">本轮试用已预留 ${e(r.budget.reserved_attempts)} / ${e(r.budget.max_attempts)} 次调用额度。失败请求也计入额度。</p>`:''}<section class="api-findings"><h3>模型建议 · ${r.review.findings.length} 项</h3>${r.review.findings.map(f=>`<article><h4>${e(f.title)}</h4><p>${e(f.detail)}</p><p>${e(f.suggestion)}</p><small>${f.page?'PDF 第 '+e(f.page)+' 页':''} ${e(f.file||'')}</small></article>`).join('')||'<p>服务未返回问题建议。</p>'}</section>`;}
 async refresh(p=this.current()){const entry=p?.api_review;if(!entry?.job||entry.mode==='synchronous')return;const generation=this.generation,client=this.client(entry.base);const job=await client.get(entry.job.id);const report=job.status==='completed'?await client.report(job):null;if(generation!==this.generation||p.api_review!==entry)return;entry.job=job;entry.report=report;await this.i.save(p);}
 async action(name){if(this.busy)return;const p=this.current();this.error='';if(name==='new')return this.i.new();if(name==='materials')return this.i.open(p.id,'materials');if(name==='export'){this.i.h.download('articheck-api-review.json',JSON.stringify(p.api_review.report,null,2));return;}this.busy=true;this.i.h.render();try{if(name==='connect'){this.health=await this.client().health();}if(name==='submit'){if(!this.consent)throw Error('先确认材料发送地址。');const base=this.base,key=materialKey(p),client=this.client(base),generation=this.generation;const health=await client.health();this.health=health;if(!health.configured)throw Error('provider_not_configured：模型服务尚未配置，未提交材料。');const job=await client.submit(p);if(generation!==this.generation)return;p.api_review={base,material_key:key,job,report:client.lastReport,mode:health.mode||'asynchronous'};this.consent=false;await this.i.save(p);}if(name==='refresh')await this.refresh(p);if(name==='cancel'){const entry=p.api_review;entry.job=await this.client(entry.base).cancel(entry.job.id);await this.i.save(p);}}catch(error){this.error=error.message;}finally{this.busy=false;this.i.h.render();}}
 afterRender(){clearTimeout(this.timer);const p=this.current();if(!['api-review','http-api'].includes(this.i.h.page())||this.busy||this.error||!['queued','running'].includes(p?.api_review?.job?.status))return;this.timer=setTimeout(async()=>{try{await this.refresh(p);}catch(error){this.error=error.message;}this.i.h.render();},2500);}
 bind(){document.addEventListener('input',event=>{if(event.target.matches('[data-review-token]'))this.token=event.target.value;});document.addEventListener('change',event=>{const t=event.target;if(t.matches('[data-review-base]')){this.base=t.value;this.health=null;this.token='';this.consent=false;this.generation++;this.i.h.render();}if(t.matches('[data-review-project]')){this.selected=t.value;this.consent=false;this.generation++;this.i.h.render();}if(t.matches('[data-review-consent]')){this.consent=t.checked;this.i.h.render();}});document.addEventListener('click',event=>{const el=event.target.closest('[data-review-action]');if(el)this.action(el.dataset.reviewAction);});}
}
